\Id &= \sum_a (\hat{M}^{(\Line,W),\line}_{[\eval_u(\cdot) =
      a]})_{\alice \alice'} \otimes I_{\bob \alice''}\notag\\
&= \sum_a \Big((\hat{M}^{(\Line,W),\line}_{[\eval_u(\cdot) =
